import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.Cq50P25D.js";var i=JSON.parse(`{"title":"Core Sync Routine","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/sync.md","filePath":"en/deep-dive/sync.md","lastUpdated":1786685097000}`),a={name:`deep-dive/sync.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="core-sync-routine" tabindex="-1">Core Sync Routine <a class="header-anchor" href="#core-sync-routine" aria-label="Permalink to “Core Sync Routine”">​</a></h1><p>The core sync routine is implemented by <code>Sync</code> in <code>packages/plugin/src/modules/Sync.ts</code>. It compares filtered local and remote stats with the persistent record store, creates a task plan, and executes the plan against the <a href="./file-system">file system abstraction</a>.</p><h2 id="sync-trigger" tabindex="-1">Sync Trigger <a class="header-anchor" href="#sync-trigger" aria-label="Permalink to “Sync Trigger”">​</a></h2><p>The scheduler accepts requests from manual controls, <a href="./../usage/settings#realtime-sync">realtime sync</a>, <a href="./../usage/settings#startup-sync">startup sync</a>, <a href="./../usage/settings#scheduled-sync">scheduled sync</a>, and migration. Trigger names are <code>manual</code>, <code>nonInteractiveManual</code>, <code>realtime</code>, <code>startup</code>, <code>interval</code>, and <code>migration</code>.</p><p>Realtime events are debounced and filtered before they schedule a request. Changes made while a sync is executing are ignored. A rename schedules a request when either its old or new path is in scope; see <a href="./../usage/settings#inclusion-and-exclusion-rules">inclusion and exclusion rules</a> for the rule configuration.</p><p>Pending requests wait until the plugin is idle, then flush as one sync. The last request supplies the trigger, and every request in the batch receives the same result. The non-interactive manual command uses a separate trigger so it can skip manual task confirmation.</p><h2 id="cancellation" tabindex="-1">Cancellation <a class="header-anchor" href="#cancellation" aria-label="Permalink to “Cancellation”">​</a></h2><p>Each run creates a cancellation reference. Stop controls, the progress modal, confirmation dialogs, and plugin cleanup dispatch <code>syncCanceled</code>. The routine checks the reference between traversal, planning, confirmation, and execution. The <a href="./file-system-wrappers#cancellation-wrapper">cancellation wrapper</a> and <a href="./request-middleware#cancellation-middleware">cancellation request middleware</a> enforce it at the filesystem and request layers.</p><p>Cancellation does not roll back completed operations. Task errors raised after cancellation are ignored, but execution waits for task promises to settle before reporting <code>cancelled</code>.</p><h2 id="traversal-and-glob-matching" tabindex="-1">Traversal and Glob Matching <a class="header-anchor" href="#traversal-and-glob-matching" aria-label="Permalink to “Traversal and Glob Matching”">​</a></h2><p>The routine compiles the configured matcher once, then starts local and remote discovery concurrently. Local traversal calls <code>localFs.list(&#39;/&#39;)</code> with the matcher. Full remote traversal receives a reporter that forwards progress and applies the matcher to each reported path.</p><p>The matcher returns <code>include</code>, <code>exclude</code>, or <code>advance</code>. Files are included or excluded; <code>advance</code> continues through a directory without including the directory itself. An excluded directory is advanced only when an inclusion rule could match a descendant. Rule syntax and matching precedence are documented in <a href="./../usage/settings#inclusion-and-exclusion-rules">Inclusion and Exclusion Rules</a>.</p><p>After discovery, <code>postTraversal</code> removes entries over the configured <a href="./../usage/settings#max-file-size">maximum file size</a> and converts the lists into stats maps.</p><h2 id="remote-lister" tabindex="-1">Remote Lister <a class="header-anchor" href="#remote-lister" aria-label="Permalink to “Remote Lister”">​</a></h2><p>Remote listing is an extension point. The registrar selects the first registered <code>RemoteLister</code> by priority. It receives the local and remote file systems, record store, trigger, and traversal reporter.</p><p>The built-in realtime fast lister uses cached <code>remoteContext20000</code> stats when <a href="./../usage/settings#realtime-sync-fast-mode">realtime sync fast mode</a> is enabled and the cache has entries. It applies the traversal reporter to cached entries but skips a fresh remote walk. Otherwise, the full lister calls <code>remoteFs.list(&#39;/&#39;)</code>.</p><p>If the remote root does not exist, the full lister recreates it, clears records for the local/remote pair, and returns an empty list.</p><h2 id="decider" tabindex="-1">Decider <a class="header-anchor" href="#decider" aria-label="Permalink to “Decider”">​</a></h2><p>The selected decider receives filtered local stats, filtered remote stats, persistent records, a task factory, and a logger. Built-in deciders union all keys found in either side or in the records. The selected <a href="./../usage/settings#sync-strategy">sync strategy</a> can be supplied by a module.</p><p><strong>Bidirectional sync strategy</strong>:</p><p>For files, it compares current stats with recorded local and remote UIDs. It creates upload, download, local removal, remote removal, record, or conflict tasks according to which side exists and changed. When both sides exist without a record, equal-size files only create a record; unequal-size files become conflicts. Missing entries on both sides produce record-removal tasks.</p><p>Folders produce directory creation, removal, or record tasks. A local/remote file-folder mismatch replaces the changed side when it can be determined; an unresolvable mismatch fails planning.</p><p><strong>Mirror local / Mirror remote sync strategy</strong>:</p><p>These two deciders make one side authoritative. They copy authoritative files, create authoritative folders, remove entries present only on the other side, and replace file-folder mismatches. A matching record avoids a redundant file transfer. Unrecorded files with matching keys and sizes receive a record; other unrecorded files are copied from the authoritative side.</p><h2 id="move-detection" tabindex="-1">Move Detection <a class="header-anchor" href="#move-detection" aria-label="Permalink to “Move Detection”">​</a></h2><p>Move detection runs after the decider. It pairs a delete task with a create task on the same side when their recorded/current file UIDs match, then replaces the pair with <code>moveLocal</code> or <code>moveRemote</code>.</p><p>It repeatedly looks for folder delete/create pairs. A folder pair is converted only when every relevant child has a compatible move into one destination and keeps its basename. New files without recorded identity, incomplete child plans, and ambiguous destinations remain ordinary delete/create operations.</p><h2 id="confirmations" tabindex="-1">Confirmations <a class="header-anchor" href="#confirmations" aria-label="Permalink to “Confirmations”">​</a></h2><p>Two confirmation gates run after move detection and before task execution. Manual task confirmation applies only to the <code>manual</code> trigger when <a href="./../usage/settings#confirm-operations-in-manual-sync">Confirm Operations in Manual Sync</a> is enabled. Add-record and remove-record tasks are omitted from the displayed list; canceling the dialog cancels the run.</p><p>Automatic local-delete confirmation applies when <a href="./../usage/settings#confirm-deletions-during-auto-sync">Confirm Deletions During Auto-Sync</a> is enabled and the trigger is <code>scheduled</code>, <code>startup</code>, or <code>realtime</code>. The dialog contains <code>removeLocal</code> tasks. Re-upload choices become upload or remote-directory creation tasks.</p><p>Both confirmation mounts a <a href="./file-tree">file tree</a> component in the progress modal.</p><h2 id="conflict-resolver" tabindex="-1">Conflict Resolver <a class="header-anchor" href="#conflict-resolver" aria-label="Permalink to “Conflict Resolver”">​</a></h2><p>Conflict tasks pass <code>key</code>, local and remote file stats, both file systems, and the record store to the selected resolver. Resolvers are registered by modules and selected by <a href="./../usage/settings#conflict-resolve-strategy">Conflict Resolve Strategy</a>. Built-in strategies and their user-facing behavior are documented there.</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};